<body>
<main>
  <header>
    <h1>File a motor claim</h1>
    <p>Private vehicle damage: collision, vandalism or broken glass. It takes about 5 minutes.</p>
  </header>

  <div id="banner" role="alert" hidden></div>

  <form id="claim" novalidate>
    <section>
